          "speaker": "SHOP OWNER ANCHOR",
          "text": "thể giúp gì- Ô! Là em\nhả?",
          "face": "",
          "faceName": "",
          "faceIndex": 0,
          "pop": true,
          "popTarget": 2,
          "background": 0,
