          "id": "m023-e041-p01-c0001",
          "kind": "dialogue",
          "speaker": "Hải Quỳ",
          "text": "Mình nhớ tủ sách này từng là\ntủ sách lịch sử phép thuật ở\nAtlantis.",
          "face": "HaiQuy_Thuongphuc_Emote.png",
          "faceName": "HaiQuy_Thuongphuc_Emote",
          "faceIndex": 1,
          "pop": false,
          "popTarget": null,
