          "kind": "dialogue",
          "speaker": "Hải Quỳ",
          "text": "Tôi cẩn thận để gói quà lên\ntrên bàn làm việc để tránh bị\ndính bẩn.",
          "face": "HaiQuy_Thuongphuc_Emote.png",
          "faceName": "HaiQuy_Thuongphuc_Emote",
          "faceIndex": 1,
          "pop": false,
          "popTarget": null,
