          "kind": "dialogue",
          "speaker": "Hải Quỳ",
          "text": "Là một kẻ tồi tệ….",
          "face": "HaiQuy_Thuongphuc_Emote.png",
          "faceName": "HaiQuy_Thuongphuc_Emote",
          "faceIndex": 1,
