          "kind": "dialogue",
          "speaker": "Hải Quỳ",
          "text": "\\cbm Tôi tính đứng lên để tặng\nchiếc máy pha cà phê cho Kohi\nthì chợt nhận ra tôi để quên",
          "face": "HaiQuy_Giangsinh_Emote.png",
          "faceName": "HaiQuy_Giangsinh_Emote",
          "faceIndex": 1,
          "pop": false,
          "popTarget": null,
