          "kind": "dialogue",
          "speaker": "Kohi",
          "text": "Đi cẩn thận nhé!!",
          "face": "Kohi_Giangsinh_Emote1.png",
          "faceName": "Kohi_Giangsinh_Emote1",
          "faceIndex": 1,
          "pop": false,
          "popTarget": null,
          "background": 0,
