          "id": "m039-e001-p01-c0867",
          "kind": "dialogue",
          "speaker": "Leo",
          "text": "Đợi tí!!",
          "face": "Leo_Giangsinh_Emote.png",
          "faceName": "Leo_Giangsinh_Emote",
          "faceIndex": 1,
          "pop": false,
          "popTarget": null,
          "background": 0,
